If we fit GP model with a kernel $k^\theta(\bm{x}, \bm{x}^\prime)$ to the data so far, $\mathcal{D}_{t-1} = \{(\bm{x}_\tau, y_\tau)\}_{\tau=1}^{t-1} $, we obtain the following mean $\mu^\theta_{t-1}(\bm{x}) $ and variance $(\sigma^\theta_{t-1})^2(\bm{x})$ functions:
\begin{equation*}
    \mu^\theta_{t-1}(\bm{x}) = \bm{k}^\theta_{t-1}(\bm{x})^T(\mathbf{K}^\theta_{t-1} + \sigma_N^2\mathbf{I})^{-1}\bm{y}_{t-1}
\end{equation*}
\begin{equation*}
    (\sigma^\theta_{t-1})^2(\bm{x}) = k^\theta(\bm{x}, \bm{x}) - \bm{k}^\theta_{t-1}(\bm{x})^T(\mathbf{K}^\theta_{t-1} + \sigma_N^2\mathbf{I})^{-1}\bm{k}^\theta_{t-1}(\bm{x}) ,
\end{equation*}
where $\bm{y}_{t-1} \in \mathbb{R}^{t-1} $ with elements $(\bm{y})_i = y_i$, $\bm{k}^\theta(\bm{x}) \in \mathbb{R}^{t-1}$ with elements $\bm{k}^\theta(\bm{x})_i = k^\theta(\bm{x}, \bm{x}_i)$ and similarily $\mathbf{K}^\theta_{t-1} \in \mathbb{R}^{t-1 \times t-1}$ with entries $(\mathbf{K}^\theta_{t-1})_{i,j} = k^\theta(\bm{x}_i, \bm{x}_j)$, and $\sigma_N^2$ is the regulariser factor \cite{chowdhury2017kernelized} with identity matrix $\mathbf{I}$.

In the case of RBF and  $\nu$-Matérn kernels, if we change the length scale value from $\theta_0$ to $\theta$ and the norm bound from $B_0$ to $B$, we  get that the regret bound with those new hyperparameters scales as follows:
\begin{equation*}
    R^{\theta,  B}(T) =  \sqrt{T}  \left(\left(\frac{B}{B_0} \right)\left(\frac{\theta_0}{\theta} \right)^{d/2}  B_0\sqrt{\gamma_T(k^{\theta_0})} + \left(\frac{\theta_0}{\theta} \right)^{d}\gamma_T(k^{\theta_0}) \right) .
\end{equation*}

On iterations up to $t_0$, we can potentially suffer the highest as possible, thus the cumulative regret can be bounded as:
\begin{equation*}
    R_T = \sum_{t=1,\dots,t_0-1}r_t + \sum_{t=t_0,\dots,T} r_t \le 2B^\star t_0 + \Tilde{R}_T ,
\end{equation*}
where $\Tilde{R}_T$ is the regret of the algorithm after $t_0$.

Let us define by $\mathcal{T}$ the set of iterations, where we reject at least one length scale value in line~\ref{alg_line:eliminate_lengthscale}. We thus have:
\begin{equation*}
    \Tilde{R}_T = \sum_{t \in \mathcal{T}} r_t + \sum_{t \notin \mathcal{T}} r_t \le 2B^\star|\mathcal{T}| +  \sum_{t \notin \mathcal{T}} r_t \le 2B^\star q^{-1}(\frac{\theta_0}{g(T)})  +  \sum_{t \notin \mathcal{T}} r_t ,
\end{equation*}
where the second inequality comes from the fact that we cannot reject more candidates than we have introduced in total.

First, we show that, with a probability of at least $1 - \delta$, the well-specified candidate introduced at $t_0$ will not be rejected. Second, since no other candidates are rejected at iterations $t \notin \mathcal{T}$, it means that the function values achieved at those iterations cannot be too different from the ones achieved when using $\hat{\theta}$. Using this fact, we arrive at a statement:
\begin{equation*}
    \sum_{t \notin \mathcal{T}} r_t \le \left(R^{\hat{\theta}}(|S_t^{\hat{\theta}}|) + \sqrt{T\xi_T}  \right) \left(\sum_{\theta \in \mathcal{M}_0}\sqrt{\frac{|S_t^{\theta}|}{|S_t^{\hat{\theta}}|}} + q^{-1} \left(\frac{\theta_0}{g(T)} \right) \right),
\end{equation*}
where $\mathcal{M}_0$ is the set of misspecified length scale values that were chosen at least once after $t_0$.

Using this fact, we arrive at a statement:
\begin{equation*}
    \sum_{t \notin \mathcal{T}} r_t \le \left(R^{\hat{\theta}}(|S_t^{\hat{\theta}}|) + \sqrt{T\xi_T}  \right) \left(\sum_{\theta \in \mathcal{M}_0}\sqrt{\frac{|S_t^{\theta}|}{|S_t^{\hat{\theta}}|}} + q^{-1} \left(\frac{\theta_0}{g(T)} \right) \right),
\end{equation*}
where $\mathcal{M}_0$ is the set of misspecified length scale values that were chosen at least once after $t_0$.

We will also write $\mathcal{T}$ to mean the set of all iterations after (and including) $t_0$, where at least one hyperparameter value was rejected, that is:
\begin{equation*}
    \mathcal{T} = \left\{ t=t_0,\dots,T \Bigg | \exists_{u \in U_t} L_t(u) +  \frac{2}{|S_t^{u}|} \sum_{\tau \in S_t^u} \beta_\tau^u \sigma^u_{\tau-1}(\bm{x}_\tau)  <  \max_{u^\prime \in U_{t}} L_t(u^\prime) \right\} .
\end{equation*}

Using this fact, we get that:
\begin{equation*}
   \frac{1}{|S_t^{u^*}|} \sum_{t \in S_t^{u^*}}\left( f(\bm{x}^*) - (y_t - \epsilon_t) \right) = \frac{1}{|S_t^{u^*}|}\sum_{t \in S_t^{u^*}}  \left(f(\bm{x}^*) - f(\bm{x}_t) \right)  \le \frac{2}{|S_t^{u^*}|}  \sum_{t \in S_t^{u^*}} \beta_t^{u^\star}\sigma_t^{u^\star}(\bm{x}_t)
\end{equation*}

Thus combining Inequalities \ref{eq:rb_lhs} and \ref{eq:rb_rhs}, we get that for any $u \in A$:
\begin{equation*}
    \frac{2}{|S_t^{u^*}|}  \sum_{t \in S_t^{u^*}} \beta_t^{u^\star}\sigma_t^{u^\star}(\bm{x}_t)  + \sqrt{\frac{\xi_t}{|S_t^{u^\star}|}}+  \sum_{t \in S_t^{u^*}} \frac{y_t}{|S_t^{u^*}|} \ge \sum_{t \in S_t^u} \frac{y_t}{|S_t^u|}   - \sqrt{\frac{\xi_t}{|S_t^u|} } ,
\end{equation*}
which means the \texttt{if} statement in line 11 will always evaluate to \texttt{true} for $u^\star$ and thus $u^* \in U_{t}$ for all $t=1, \dots, T$.

We will prove the statement by contradiction. If the statement of the Lemma was not true, we would have:
    \begin{equation*}
        R^{u}(|S_t^u|) > R^{u^\star}(|S_t^{u^\star}|) + 2B^{u^\star} \ge R^{u^\star}(|S_t^{u^\star}| + 1),
    \end{equation*}
    where the second inequality comes from the assumption that the bounds are non-trivial.

Multiplying both sides by $-1$ and adding $f(\bm{x}^*)$, we get:
\begin{equation*}
      \frac{1}{|S_{t^\prime}^{u}|} \sum_{\substack{t \notin \mathcal{T} \\     t \in S_{t^\prime}^{u}}} \left(f(\bm{x}^*) - y_t\right) - \frac{2\sum_{t \in S_{t^\prime}^{u}} \beta_t^{u}\sigma_t^{u}(\bm{x}_t) }{|S_{t^\prime}^{u}|}   - \sqrt{\frac{\xi_t}{|S_{t^\prime}^{u}|}}  \le \frac{1}{|S_{t^\prime}^{u^\star}|} \sum_{t \in S_{t^\prime}^{u^\star}} \left(f(\bm{x}^*) - y_t \right)  + \sqrt{\frac{\xi_t}{|S_{t^\prime}^{u^\star}|} } .
\end{equation*}

Using the fact that $y_t = f(\bm{x}_t) + \epsilon_t$ and Lemma \ref{lemma:noisebound} we get that:
\begin{align*}
      \frac{1}{|S_{t^\prime}^{u}|} \sum_{\substack{t \notin \mathcal{T} \\     t \in S_{t^\prime}^{u}}} \left(f(\bm{x}^*) - f(\bm{x}_t)\right) -\frac{2\sum_{t \in S_{t^\prime}^{u}} \beta_t^{u}\sigma_t^{u}(\bm{x}_t) }{|S_{t^\prime}^{u}|}  - 2\sqrt{\frac{\xi_t}{|S_{t^\prime}^{u}|}}  \\
      \le \frac{1}{|S_{t^\prime}^{u^\star}|} \sum_{t \in S_{t^\prime}^{u^\star}} \left(f(\bm{x}^*) - f(\bm{x}_t) \right)  + 2\sqrt{\frac{\xi_t}{|S_{t^\prime}^{u^\star}|} } .
\end{align*}

Rearranging and observing that $r_t = f(\bm{x}^\star) - f(\bm{x}_t)$, we obtain:
\begin{align*}
\sum_{\substack{t \notin \mathcal{T} \\     t \in S_{t^\prime}^{u}}} r_t    \le &  2\sum_{t \in S_{t^\prime}^{u}} \beta_t^{u}\sigma_t^{u}(\bm{x}_t) + 2\sqrt{|S_{t^\prime}^{u}|\xi_t} +  \frac{|S_{t^\prime}^{u}|}{|S_{t^\prime}^{u^\star}|} \sum_{t \in S_{t^\prime}^{u^\star}} r_t  + 2|S_{t^\prime}^{u}|\sqrt{\frac{\xi_t}{|S_{t^\prime}^{u^\star}|} } \\
\le &  C R^{u}(|S_{t^\prime}^{u}|)+ 2\sqrt{|S_{t^\prime}^{u}|\xi_t}+  \frac{|S_{t^\prime}^{u}|}{|S_{t^\prime}^{u^\star}|} CR^{u^\star}(|S_{t^\prime}^{u^\star}|) + 2|S_{t^\prime}^{u}|\sqrt{\frac{\xi_t}{|S_{t^\prime}^{u^\star}|} },
\end{align*}
where we use the fact that $2\sum_{t \in S_{t^\prime}^{u}} \beta_t^{u}\sigma_t^{u}(\bm{x}_t) \le CR^{u}(S_{t^\prime}^{u})$ for some constant $C > 0$, which follows from the proof of Theorem 2 of \cite{chowdhury2017kernelized} on which we rely to obtain the suspected regret bounds. We also used the fact that due to $u^\star$ being well-specified we have that $\sum_{t \in S_T^{u^\star}} r_t \le C R^{u^\star}(|S_T^{u^\star}|)$.

Observe, that suspected regret bounds in BO will be of form $R^u(T) = \sqrt{T \beta^u_T \gamma_T^u} (\sqrt{\gamma_T^u} + \sqrt{B^u})$. Substituting this fact, we get:
\begin{align*}
    R^{u^*}(|S_T^{u^*}|)\sum_{u \in \mathcal{M}_0} \frac{|S_T^{u}|}{|S_T^{u^*}|} &\le \mathcal{O}\left( \sum_{u \in \mathcal{M}_0} \frac{|S_T^{u}|}{|S_T^{u^*}|} \sqrt{|S_T^{u^*}| \beta^{u^\star}_T \gamma_T^u} \left(\sqrt{\gamma_T^{u^\star}} + \sqrt{B^{u^\star}} \right)\right) \\
    & =  \mathcal{O}\left( \sum_{u \in \mathcal{M}_0} \sqrt{\frac{|S_T^{u}|}{|S_T^{u^*}|}} \sqrt{ |S_T^{u}|\beta^{u^\star}_T \gamma_T^u} \left(\sqrt{\gamma_T^{u^\star}} + \sqrt{B^{u^\star}} \right)\right) \\
    & =  \mathcal{O}\left( \sum_{u \in \mathcal{M}_0} \sqrt{\frac{|S_T^{u}|}{|S_T^{u^*}|}} R^{u^\star}(|S_T^{u}|)\right) \\
    & \le  \mathcal{O}\left(  \sum_{u \in \mathcal{M}_0} \sqrt{\frac{|S_T^{u}|}{|S_T^{u^*}|}} R^{u^\star}(T)\right) .
\end{align*}
We thus get :
\begin{equation*}
\sum_{u \in\mathcal{M}_0} \sum_{\substack{t \notin \mathcal{T} \\ t \in S_T^u }} r_t = \mathcal{O} \left(|\mathcal{M}_0|B^{u^\star} + \left(R^{u^*}(T) + \sqrt{T\xi_T}  \right) \left(\sum_{u \in \mathcal{M}_0}\sqrt{\frac{|S_T^{u}|}{|S_T^{u^*}|}} + |\mathcal{M}_0| \right) \right) .
\end{equation*}

Substituting this back into Equation \ref{eq:regretbalacningincompletebound} yields the following bound:
\begin{equation*}
    \sum_{t \notin \mathcal{T}} r_t \le \mathcal{O} \left(|A|B^{u^\star} + \left(R^{u^*}(T) + \sqrt{T\xi_T}  \right) \left(\sum_{u \in \mathcal{M}_0}\sqrt{\frac{|S_T^{u}|}{|S_T^{u^*}|}} + |A| \right) \right) 
\end{equation*}

Let $t_0$ be the first iteration, where a length scale value smaller or equal to $\theta^\star$ enters the hyperparameter set $\Theta_{t_0}$. We will refer to that value as $\hat{\theta}$. Before this happens, all hyperparameters in the set are misspecified and as such we cannot guarantee anything about the regret of those iterations. As such, we bound their regret by $2B^\star$, which is the highest possible regret one can suffer at one iteration. We thus get:
\begin{equation} R_T = \sum_{t=1,\dots,t_0} r_t + \sum_{t=t_0+1,\dots,T} r_t \le t_02B^\star + \Tilde{R}_T
\end{equation}

We note that due to how we add new length scales, we have that $t_0 \le g^{-1}(\frac{\theta_0}{\theta^\star e^{1/d}}) $ and we defined $\Tilde{R}_T$ be the cumulative regret of all iterations after $t_0$. Let us define the set $\mathcal{T}$ to be the set of all iterations, where at least one hyperparameter was eliminated. We thus get the following regret bound:
\begin{equation*}
    \Tilde{R}_T = \sum_{t \in \mathcal{T}} r_t + \sum_{t \notin \mathcal{T}} r_t \le 2|\mathcal{T}|B^\star + \sum_{t \notin \mathcal{T}} r_t  \le 2q^{-1}\left(\frac{\theta_0}{g(T)}\right)B^\star + \sum_{t \notin \mathcal{T}} r_t,
\end{equation*}
where the last inequality comes from the fact that we cannot reject more hyperparameters than we have considered in total.

We now rely on Lemma \ref{lemma:regretbalancing}, which provides a bound on $\sum_{t \notin \mathcal{T}} r_t$ with probability at least $1 - \delta_A - \delta_B$ and we set $\delta_A = \delta_B = \delta / 2$. 
In the notation of the Lemma, we can write $A = \underset{t=1,\dots,T}{\bigcup}\Theta_t $ to mean the set of all length scale values introduced over the course of the algorithm running and by $\mathcal{M}_0$ we mean all length scales longer than $\hat{\theta}$ that were selected at least once after $t_0$. We observe that $|A| \le q^{-1}\left(\frac{\theta_0}{g(T)}\right)$ and our optimal base learner is $u^\star = \hat{\theta}$. This gives us:
\begin{equation*}
     \sum_{t \notin \mathcal{T}} r_t  = \mathcal{O} \left(q^{-1}\left(\frac{\theta_0}{g(T)}\right)B^\star + \left(R^{\hat{\theta}}(T) + \sqrt{T\xi_T}  \right) \left( \sum_{u \in \mathcal{M}_0}\sqrt{\frac{|S_T^{u}|}{|S_T^{u^*}|}} + q^{-1}\left(\frac{\theta_0}{g(T)}\right) \right) \right)
\end{equation*}

To finish the proof we rely on the following Lemma, which we prove in Appendix \ref{app:rbfbalancingbound_proof}.
\begin{restatable}[]{lemma}{rbfbalancingbound} If the event of Lemma \ref{lemma:regretbalancing} holds, then for any $\theta \in \mathcal{M}_0$ and $t \ge t_0$ we have that $\sqrt{\frac{|S_t^{\theta}|}{|S_t^{\theta^\star}|}} \le \left(\frac{\theta_0}{\theta^\star}\right)^{d} $.

\end{restatable}

We thus get the following final bound:
\begin{equation*}
     \sum_{t \notin \mathcal{T}} r_t = \mathcal{O} \left(q^{-1}\left(\frac{\theta_0}{g(T)}\right)B^\star + \left(R^{\hat{\theta}}(T) + \sqrt{T\xi_T}  \right) \left( |\mathcal{M}_0|\left(\frac{\theta_0}{\theta^\star} \right)^{d} + q^{-1}\left(\frac{\theta_0}{g(T)}\right) \right) \right).
\end{equation*}
We now observe that $|\mathcal{M}_0| = \mathcal{O}\left(q^{-1}\left(\theta^\star\right)\right) = \mathcal{O}\left(d \ln \frac{\theta_0}{\theta^\star} \right)$. We substitute the bound above to Equation \ref{eq:mainprooffirstdecomp}, together with bound on $|\mathcal{M}_0|$ to obtain:
\begin{equation*}
     R_T \le \mathcal{O} \left(\left(g^{-1}\left(\frac{\theta_0}{\theta^\star e^{1/d}} \right)+ \iota \right)B^\star + \left(R^{\hat{\theta}}(T) + \sqrt{T\xi_T}  \right) \left(\left(\frac{\theta_0}{\theta^\star} \right)^{d}d \ln \theta^\star + \iota \right) \right),
\end{equation*}
where $\iota = d \ln g(T)$.

If $|S_t^{\theta^\star}| \ge |S_t^{\theta}|$, the bound holds trivially. Thus we will assume $|S_t^{\theta^\star}| < |S_t^{\theta}|$. The suspected regret bounds are of the form:
    \begin{equation*}
        R^\theta(T) =  \sqrt{T\gamma_T^\theta} \left( \sqrt{\gamma_T^\theta} + B(\theta, N^\star) \right) .
    \end{equation*}
    If the event on Lemma \ref{lemma:regretbalancing} holds that means the event of Lemma \ref{lemma:balancedbounds} holds as well. Due to the regret balancing condition from Lemma \ref{lemma:balancedbounds} and the non-triviality of bounds, we have:
    \begin{equation*}
         R^{\theta}(|S_t^{\theta}|) \le  R^{\theta^\star}(|S_t^{\theta^\star}|) + 2B^{u^\star} \le  2R^{\theta^\star}(|S_t^{\theta^\star}|)
    \end{equation*}
    \begin{equation*}
         \sqrt{\frac{|S_t^{\theta}|}{|S_t^{\theta^\star}|}}  \le  2 \frac{ \sqrt{\gamma_{|S_t^{\theta^\star}|}^\theta} \left( \sqrt{\gamma_{|S_t^{\theta^\star}|}^\theta} + B(\theta^\star, N^\star) \right)}{ \sqrt{\gamma_{|S_t^{\theta}|}^\theta} \left( \sqrt{\gamma_{|S_t^{\theta}|}^\theta} + B(\theta, N^\star) \right)} .
    \end{equation*}
    To finish the proof we consider the following two cases.

\textbf{Case 1:} Consider the case when $\sqrt{\gamma_{|S_t^{\theta^\star}|}^\theta} \ge B(\theta^\star, N^\star)$. We then have:
    \begin{equation*}
         \sqrt{\frac{|S_t^{\theta}|}{|S_t^{\theta^\star}|}}  \le  2 \frac{ \gamma_{|S_t^{\theta^\star}|}^\theta}{ \gamma_{|S_t^{\theta}|}^\theta} \le 2 \left(\frac{\theta}{\theta^\star} \right)^{d} \frac{ \gamma_{|S_t^{\theta}|}^\theta}{ \gamma_{|S_t^{\theta}|}^\theta} = 2 \left(\frac{\theta}{\theta^\star} \right)^{d} \le 2 \left(\frac{\theta_0}{\theta^\star} \right)^{d}.
    \end{equation*}

\textbf{Case 2} Consider the case when $\sqrt{\gamma_{|S_t^{\theta^\star}|}^\theta} < B(\theta^\star, N^\star)$. We then have:
    \begin{align*}
         \sqrt{\frac{|S_t^{\theta}|}{|S_t^{\theta^\star}|}}  &\le  2 \frac{ \sqrt{\gamma_{|S_t^{\theta^\star}|}^\theta}B(\theta^\star, N^\star)}{ \sqrt{\gamma_{|S_t^{\theta}|}^\theta} B(\theta, N^\star)} \le  2 \left(\frac{\theta}{\theta^\star} \right)^{d/2} \sqrt{\frac{ \gamma_{|S_t^{\theta}|}^\theta}{ \gamma_{|S_t^{\theta}|}^\theta}} \left(\frac{\theta}{\theta^\star} \right)^{d / 2} \frac{B(\theta, N^\star)}{B(\theta, N^\star)} \\
         &\le 2 \left(\frac{\theta}{\theta^\star} \right)^{d} \le 2 \left(\frac{\theta_0}{\theta^\star} \right)^{d}.
    \end{align*}

\textbf{Case 1: $\sqrt{\gamma_T^{\hat{\theta}}} > B(\hat{\theta}, \hat{N})$}
    \begin{equation*}
        \frac{R^{(\hat{\theta}, B(\hat{\theta}, \hat{N}))}(T)}{R^{(\theta^\star, B(\theta^\star, N^\star))}(T)} = \frac{ \sqrt{T\gamma_T^{\hat{\theta}}} \left( \sqrt{\gamma_T^{\hat{\theta}}} + B(\hat{\theta}, \hat{N}) \right)}{ \sqrt{T\gamma_T^{\theta^\star}} \left( \sqrt{\gamma_T^{\theta^\star}} + B(\theta^\star, N^\star) \right)} \le  2\left(\frac{\theta^\star}{\hat{\theta}}\right)^{d} \le  2\left(\frac{q(i^\star)}{q(i^\star + 1)}\right)^{d} = 2\left(e^{-1/d}\right)^{d} = \mathcal{O}(1),
    \end{equation*}
    where $i^\star = \max \{ i \in \mathbb{N} \mid q(i) \ge \theta^\star \}$ and as such we have $q(i^\star + 1) = \hat{\theta} \le \theta^\star \le  q(i^\star) r$.

\textbf{Case 2: $\sqrt{\gamma_T^{\hat{\theta}}} \le B(\hat{\theta}, \hat{N})$}
\begin{align*}
        \frac{R^{(\hat{\theta}, B(\hat{\theta}, \hat{N}))}(T)}{R^{(\theta^\star, B(\theta^\star, N^\star))}(T)} &= \frac{ \sqrt{T\gamma_T^{\hat{\theta}}} \left( \sqrt{\gamma_T^{\hat{\theta}}} + B(\hat{\theta}, \hat{N}) \right)}{\sqrt{T\gamma_T^{\theta^\star}} \left( \sqrt{\gamma_T^{\theta^\star}} + B(\theta^\star, N^\star) \right)} \le  \frac{2  \sqrt{\gamma_T^{\hat{\theta}}} B(\hat{\theta}, \hat{N}) }{\sqrt{\gamma_T^{\theta^\star}}  B(\theta^\star, N^\star)} \le 2\left(\frac{q(i^\star)}{q(i^\star + 1)}\right)^{d} \frac{v(j^\star+1)}{v(j^\star)} \\
        &\le 2\left(e^{-1/d}\right)^{d} e = 2 = \mathcal{O}(1)
    \end{align*}
    where $i^\star = \max \{ i \in \mathbb{N} \mid q(i) \ge \theta^\star \}$ and $j^\star = \max \{ j \in \mathbb{N} \mid  v(j) \le N^\star   \}$ as such we have $q(i^\star + 1) = \hat{\theta} \le \theta^\star \le  q(i^\star) $ and $v(j^\star + 1) = \hat{N} \ge  N^\star \ge v(j^\star)$.

Similarly as in the proof of Theorem \ref{thm:fullrbbound}, we look for $t_0$, such that at least one well-specified hyperparameter value will enter the considered set. This happens after at most $t_0 = \max\{g^{-1}(\frac{\theta_0}{\theta^\star e^{1/d}}), b^{-1}(\frac{B}{B_0}e)\}$. Observe that the set of all hyperparameters introduced by time step $T$ is $A = \Theta_T \times \mathcal{B}_t$. We thus have:
    \begin{equation*}
        R_T \le 2t_0B + |A|B + \sum_{t \notin \mathcal{T}} r_t.
    \end{equation*}

We now apply Lemma \ref{lemma:regretbalancing}  to get:
    \begin{equation*}
        \sum_{t \notin \mathcal{T}} r_t \le \mathcal{O} \left(|A|B + \left(R^{u^*}(T) + \sqrt{T\xi_T}  \right) \left(\sum_{u \in \mathcal{M}_0}\sqrt{\frac{|S_T^{u}|}{|S_T^{u^*}|}} + |A| \right) \right),
    \end{equation*}
    where now $|A| = |\Theta_T||\mathcal{B}_T| = q^{-1}(\frac{\theta_0}{g(T)}) v^{-1}(N_0 b(T)) = d \log(g(T)) \log(b(T))$.

We now derive a Lemma similar to Lemma \ref{lemma:rbfbalancingbound}.
\begin{restatable}[]{lemma}{rkhsbalancing} If the event of Lemma \ref{lemma:regretbalancing} holds, then for any $\theta \in \mathcal{M}_0$ and $t \ge t_0$ we have that $$\sqrt{\frac{|S_t^{u}|}{|S_t^{u^*}|}} \le \left(\frac{\theta_0}{\theta^\star}\right)^{d}\frac{N^\star}{N_0} .$$

\end{restatable}

If $|S_t^{u^*}| \ge |S_t^{u}|$, the bound holds trivially. Thus we will assume $|S_t^{u^*}| < |S_t^{u}|$. The suspected regret bounds are of the form:
    \begin{equation*}
        R^u(t) = \sqrt{T\gamma_T^\theta} \left( \sqrt{\gamma_T^\theta} + B(\theta, N) \right) .
    \end{equation*}
    Due to the regret balancing condition (Lemma 5.2 of \cite{pacchiano2020regret}), we must have:
    \begin{equation*}
         R^{u}(|S_t^{u}|) \le  2R^{u^*}(|S_t^{u^*}|)
    \end{equation*}
    \begin{equation*}

\textbf{Case 1:} Consider the case when $\sqrt{\gamma_{|S_t^{\theta^\star}|}^{\theta^\star}} \ge B(\theta^\star, N^\star)$. We then have:
    \begin{equation*}
         \sqrt{\frac{|S_t^{u}|}{|S_t^{u^*}|}}  \le  2 \frac{ \gamma_{|S_t^{u^*}|}^{\theta^\star}}{ \gamma_{|S_t^{u}|}^\theta} \le 2 \left(\frac{\theta}{\theta^\star} \right)^{d} \frac{ \gamma_{|S_t^{u}|}^\theta}{ \gamma_{|S_t^{u}|}^\theta} = 2 \left(\frac{\theta}{\theta^\star}  \right)^{d} \le  2 \left(\frac{\theta_0}{\theta^\star}  \right)^{d} \frac{N^\star}{N_0} .
    \end{equation*}

\textbf{Case 2} Consider the case when $\sqrt{\gamma_{|S_t^{u^*}|}^{\theta^\star}} < B(\theta^\star, N^\star)$. We then have:
    \begin{align*}
         \sqrt{\frac{|S_t^{u}|}{|S_t^{u^*}|}}  &\le  2 \frac{ \sqrt{\gamma_{|S_t^{u^*}|}^{\theta^\star}}B(\theta^\star, N^\star)}{ \sqrt{\gamma_{|S_t^{u}|}^\theta} B(\theta, N)} \le  2 \left(\frac{\theta}{\theta^\star} \right)^{d/2} \sqrt{\frac{ \gamma_{|S_t^{u}|}^{\theta^\star}}{ \gamma_{|S_t^{u}|}^\theta}} \frac{B(\theta^\star, N^\star)}{B(\theta, N)} = 2 \left(\frac{\theta}{\theta^\star} \right)^{d} \frac{N^\star}{N} \\
         & \le 2 \left(\frac{\theta_0}{\theta^\star}  \right)^{d} \frac{N^\star}{N_0}  .
    \end{align*}

